		assert.ok(oParser.parse(), 'Test: TINV("0.05",10) is parsed.');
		assert.strictEqual(oParser.calculate().getValue(), 2.2281388519862753, 'Test: Positive case: String. String convertible to valid probability. 2 arguments used.');
