		assert.strictEqual(oParser.calculate().getValue(), "#NUM!");

		oParser = new parserFormula("GAMMA(-2)", "A1", ws);
		assert.ok(oParser.parse());
		assert.strictEqual(oParser.calculate().getValue(), "#NUM!");

		// 	Data for reference link. Use A100-A111
