		let ws2 = getSecondSheet();
		ws2.getRange2("A1").setValue("18.307");
		ws2.getRange2("A2").setValue("10");
		ws2.getRange2("A3").setValue("test");
		ws2.getRange2("A4").setValue("#N/A");
