		assert.strictEqual(oParser.calculate().getValue(), 0.000038477, 'Test: Bounded case: Number(2). x=1, maximum positive n value. 2 arguments used.');


		testArrayFormula2(assert, "BESSELJ", 2, 2, true, null);
