		ws.getRange2("I6").setValue("B");
		ws.getRange2("I7").setValue("C");

		// Test with 11 arguments (1 sum_range + 5 criteria pairs)
		oParser = new parserFormula("SUMIFS(E2:E7, F2:F7, \"Red\", G2:G7, \"Large\", H2:H7, 2024, I2:I7, \"A\", I2:I7, \"*\")", "A1", ws);
