		assert.ok(oParser.parse(), 'Test: SINH(A106:A107) is parsed.');
		//? assert.strictEqual(oParser.calculate().getValue(), 0, 'Test: Negative case: Area. Area with text in one cell returns #VALUE!. 1 argument used.');
