		assert.ok(oParser.parse(), "RANDBETWEEN(TRUE,TRUE) in cells");
		assert.strictEqual(oParser.calculate().getValue(), "#VALUE!", "Result RANDBETWEEN(TRUE,TRUE) in cells");

		oParser = new parserFormula("RANDBETWEEN(A14,A7)", "A2", ws);
