		oParser = new parserFormula("RANDBETWEEN(A16,A16)", "A2", ws);
		assert.ok(oParser.parse(), "RANDBETWEEN(,) in cells");
		assert.strictEqual(oParser.calculate().getValue(), 0, "Result RANDBETWEEN(,) in cells");

