		// Positive cases:
		// Case #0: Number(3), Array. Basic valid input: numbers for x, n, m, and array for coefficients. 4 of 4 arguments used.
		oParser = new parserFormula('SERIESSUM(2,1,1,{1,2,3})', 'A2', ws);
