		ws2.getRange2("B18").setValue("-0.8"); // TestNameArea3D2


		// Positive cases:
		// Case #1: Number. Basic valid input: positive numbers, cumulative TRUE. Returns cumulative distribution.
		oParser = new parserFormula('EXPONDIST(1,2,TRUE)', 'A2', ws);
