		assert.ok(oParser.parse(), 'Test: LCM(TestName1,TestName2) is parsed.');
		assert.strictEqual(oParser.calculate().getValue(), 0, 'Test: Positive case 10: Name(2). Arguments as named ranges. 2 of 2 arguments used.');
