		ws2.getRange2("B18").setValue("-0.8"); // TestNameArea3D2

		// Positive cases:
		// Case #0: Number. Basic valid input: numbers with a mode. 3 arguments used.
		oParser = new parserFormula('MODE.SNGL(2,2,3)', 'A2', ws);
