		assert.ok(oParser.parse(), 'Test: PERCENTILE({1,2,3}, 1.1) is parsed.');
		assert.strictEqual(oParser.calculate().getValue(), '#NUM!', 'Test: Negative case: Number, Number. k > 1 returns #NUM!.');
