		// Case #12: Table. Table structured refs.
		// Case #2: String. Non-numeric strings return #VALUE!.
		// Case #8: Area3D. 3D ref to text returns #VALUE
		// Case #9: Name. Named area.

		oParser = new parserFormula("MDETERM({1,2;10,11})", "A2", ws);
