		assert.ok(oParser.parse(), 'Test: UPPER(Sheet2!A2) is parsed.');
		assert.strictEqual(oParser.calculate().getValue(), '#N/A', 'Test: Negative case: Ref3D. 3D ref to error returns #VALUE!. 1 argument used.');
