		assert.strictEqual(oParser.calculate().getElementRowCol(0, 1).getValue().toFixed(4) - 0, 123, "Result of GROWTH({123,123},{123,123}) [0,1]");

		oParser = new parserFormula("GROWTH({2,8},{1,1})", "A2", ws);
