		assert.ok(oParser.parse(), 'Test: FIND("*","This is text*",1) is parsed.');
		assert.strictEqual(oParser.calculate().getValue(), 13, 'Test: Negative case: String. Wildcard (*) not allowed, treated as literal. Returns 12.');
